const BATTLE_SESSION_KEY='curiona.battle.session.v1';
const BATTLE_NAME_KEY='curiona.battle.name.v1';
let battleIdentity=null,battleRoom=null,battleRooms=[],battleBusy=false,battlePoll=null,battleClock=null,battleFetching=false,battleEpoch=0,battleListLoaded=false,battleServerOffset=0,battleError='',battlePendingAnswer=null,battleLiveSignature='',battleDirectoryPoll=null,battleDirectoryRequest=0;
const battleDraft={name:'',title:'Le groupe des curieux',theme:'all',themes:['all'],visibility:'public',difficulty:'all',count:'8',maxPlayers:'8',listed:true,password:'',code:'',joinPassword:'',matchTheme:'all',search:'',filterTheme:'all'};
const battleRoundDraft={key:'',theme:'all',themes:['all'],visibility:'private',difficulty:'all',count:'8',maxPlayers:'8',listed:false};
function battleRoundId(room=battleRoom){return Number.isSafeInteger(room?.roundId)?room.roundId:1;}
function battleGroupDraft(){
  const key=(battleRoom?.code||'')+':'+battleRoundId();
  if(battleRoundDraft.key!==key)Object.assign(battleRoundDraft,{key,theme:battleRoom.theme,themes:battleRoomThemes(battleRoom),visibility:battleRoomVisibility(battleRoom),difficulty:String(battleRoom.difficulty),count:String(battleRoom.count),maxPlayers:String(battleRoom.maxPlayers),listed:!!battleRoom.listed});
  return battleRoundDraft;
}
function battleGroupDirty(){
  if(!battleRoom||battleRoundDraft.key!==battleRoom.code+':'+battleRoundId())return false;
  return ['difficulty','count','maxPlayers'].some(k=>String(battleRoundDraft[k])!==String(battleRoom[k]))||battleRoundDraft.visibility!==battleRoomVisibility(battleRoom)||JSON.stringify(battleNormalizeThemes(battleRoundDraft.themes))!==JSON.stringify(battleRoomThemes(battleRoom));
}

function battleGroupOptions(next=false){
  if(!battleHost())return next?'<section class="battle-panel battle-next-wait"><h2>On continue ensemble ?</h2><p>L’hôte peut préparer une nouvelle manche dans ce même groupe. Tu gardes ta place, le code et le chat.</p></section>':'';
  const d=battleGroupDraft(),kind=next?'round-next':'room-configure';
  const select=(key,label,options)=>`<div class="form-field"><label for="battle-round-${key}">${label}</label><select id="battle-round-${key}" data-battle-round-field="${key}">${options.map(([value,text])=>`<option value="${value}" ${String(d[key])===String(value)?'selected':''} ${key==='maxPlayers'&&Number(value)<battleActivePlayers().length?'disabled':''}>${text}</option>`).join('')}</select></div>`;
  return `<section class="battle-panel battle-group-options"><div class="eyebrow">Même groupe · même code · même chat</div><h2>${next?'Partie suivante':'Préparer cette manche'}</h2><p>${next?'Change le programme si tu le souhaites. Les joueurs gardent leur place ; tu lanceras ensuite la partie quand vous serez prêts.':'Choisis les univers et les options, applique-les, puis lance la battle quand au moins deux joueurs sont connectés.'}</p><form data-battle-form="${kind}" data-round-key="${esc(d.key)}">${battleThemePicker('round',d)}<div class="battle-form-grid">${select('difficulty','Difficulté',[['all','Tous les niveaux'],[1,'Débutant'],[2,'Intermédiaire'],[3,'Avancé'],[4,'Expert']])}${select('count','Nombre de questions',[[8,'8 questions'],[12,'12 questions'],[20,'20 questions'],[50,'50 questions']])}${select('maxPlayers','Places du groupe',Array.from({length:7},(_,i)=>[i+2,(i+2)+' joueurs maximum']))}</div><p class="form-hint battle-capacity-warning" data-battle-capacity-warning role="status" hidden></p>${battleVisibilityPicker('round',d)}<p class="form-hint" data-battle-access-hint="round">${battleAccessHint(d,true)}</p><p class="form-hint">Les membres hors ligne gardent leur place. Un filtre très précis peut raccourcir la manche.</p><button class="primary" type="submit" ${battleBusy?'disabled':''}>${next?'Préparer la partie suivante':'Appliquer les options'} ${icon('arrow')}</button></form></section>`;
}
try{battleDraft.name=localStorage.getItem(BATTLE_NAME_KEY)||'';}catch{}
try{const saved=JSON.parse(sessionStorage.getItem(BATTLE_SESSION_KEY)||'null');if(saved&&typeof saved.code==='string'&&typeof saved.token==='string'&&typeof saved.playerId==='string')battleIdentity=saved;}catch{}
function battleRemember(){try{if(battleIdentity)sessionStorage.setItem(BATTLE_SESSION_KEY,JSON.stringify(battleIdentity));else sessionStorage.removeItem(BATTLE_SESSION_KEY);}catch{}}
function battleNormalizeThemes(themes){
  const values=Array.isArray(themes)?themes.filter(key=>key==='all'||CATEGORIES.some(c=>key===c.id||c.subs.some(sub=>key===c.id+'::'+sub))):[];
  if(values.includes('all'))return ['all'];
  const unique=[...new Set(values)];
  return unique.filter(key=>!key.includes('::')||!unique.includes(key.split('::')[0])).sort();
}
function battleRoomThemes(room){return battleNormalizeThemes(Array.isArray(room?.themes)?room.themes:[room?.theme||'all']);}
function battleRoomVisibility(room){return room?.visibility||(room?.listed&&!room?.locked?'public':'private');}
function battleThemeLabel(key){
  if(Array.isArray(key))return key.length?key.map(battleThemeLabel).join(' + '):'Choisis tes univers';
  if(key&&typeof key==='object')return battleThemeLabel(battleRoomThemes(key));
  if(!key||key==='all')return 'Tous les univers';
  if(key==='mixed')return 'Mélange d’univers';
  const [category,sub]=key.split('::'),c=CATEGORIES.find(c=>c.id===category);
  return sub?`${c?.name||category} · ${sub}`:c?.name||key;
}
function battleThemePicker(scope,d){
  const selected=battleNormalizeThemes(d.themes),all=selected.includes('all'),prefix=scope==='round'?'battle-round':'battle',single=selected.length===1?selected[0]:'mixed';
  return `<fieldset class="battle-theme-picker" data-battle-picker="${scope}"><legend>Les univers de cette battle</legend><p>Coche un ou plusieurs univers pour les mélanger, par exemple Nature + Politique.</p><label class="battle-theme-choice battle-theme-all"><input type="checkbox" data-battle-theme-choice="all" data-battle-theme-scope="${scope}" ${all?'checked':''}><span>Tous les univers</span></label><div class="battle-theme-grid">${CATEGORIES.map(c=>`<label class="battle-theme-choice"><input type="checkbox" data-battle-theme-choice="${c.id}" data-battle-theme-scope="${scope}" ${selected.includes(c.id)?'checked':''}><span>${icon(c.icon)}${esc(c.name)}</span></label>`).join('')}</div><p class="battle-theme-summary" data-battle-theme-summary="${scope}" aria-live="polite">${esc(battleThemeLabel(selected))}</p><details class="battle-precise-theme"><summary>Choisir un sous-thème ou un continent précis</summary><div class="form-field"><label for="${prefix}-theme">Thème précis <span class="muted">(remplace le mélange)</span></label><select id="${prefix}-theme" ${scope==='round'?'data-battle-round-field':'data-battle-field'}="theme"><option value="mixed" ${single==='mixed'?'selected':''} disabled>Mélange de plusieurs univers</option>${battleThemes(single)}</select></div></details></fieldset>`;
}
function battleVisibilityPicker(scope,d){
  const field=scope==='round'?'data-battle-round-field':'data-battle-field';
  return `<fieldset class="battle-access-picker"><legend>Qui peut rejoindre ?</legend><div class="battle-access-options"><label><input type="radio" name="${scope}-visibility" value="public" ${field}="visibility" ${d.visibility==='public'?'checked':''}><span><strong>${icon('globe')} Mondial · ouvert</strong><small>Visible dans la liste, entrée directe sans code.</small></span></label><label><input type="radio" name="${scope}-visibility" value="private" ${field}="visibility" ${d.visibility==='private'?'checked':''}><span><strong>${icon('lock')} Privé · entre amis</strong><small>Accès par code, lien ou invitation d’un ami.</small></span></label></div></fieldset>`;
}
function battleAccessHint(d,existing=false){
  if(d.visibility==='public')return existing&&battleRoom?.locked?'En choisissant Mondial, tu ouvres le groupe à tous et retires son mot de passe. L’hôte lance toujours la partie.':'Ton groupe apparaît parmi les groupes mondiaux ouverts. Les joueurs le rejoignent directement, puis tu lances la partie.';
  return existing&&battleRoom?.locked?'Ton groupe reste privé et conserve son mot de passe. Invite tes amis ou partage son code.':'Ton groupe est masqué dans la liste mondiale. Invite tes amis ou partage le code et, si tu en choisis un, le mot de passe.';
}
function battleUpdateThemePicker(scope){
  const d=scope==='round'?battleRoundDraft:battleDraft,selected=battleNormalizeThemes(d.themes),root=document.querySelector(`[data-battle-picker="${scope}"]`);
  if(!root)return;
  root.querySelectorAll('[data-battle-theme-choice]').forEach(input=>input.checked=selected.includes(input.dataset.battleThemeChoice));
  const summary=root.querySelector('[data-battle-theme-summary]');if(summary)summary.textContent=battleThemeLabel(selected);
  const precise=root.querySelector('select');if(precise)precise.value=selected.length===1?selected[0]:'mixed';
}
function battleChosenThemes(d){const themes=battleNormalizeThemes(d.themes);if(!themes.length)throw Error('Choisis au moins un univers ou Tous les univers.');return themes;}
function battleThemes(selected){return `<option value="all" ${selected==='all'?'selected':''}>Tous les univers</option>${CATEGORIES.map(c=>`<optgroup label="${esc(c.name)}"><option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)} · ${c.id==='politics'?'général, tous les continents':'tout l’univers'}</option>${c.subs.map(s=>{const key=c.id+'::'+s;return `<option value="${esc(key)}" ${selected===key?'selected':''}>${esc(s)}</option>`;}).join('')}</optgroup>`).join('')}`;}
function battleSelect(id,label,options,value){return `<div class="form-field"><label for="${id}">${label}</label><select id="${id}" data-battle-field="${id.replace('battle-','')}">${options.map(([v,text])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${text}</option>`).join('')}</select></div>`;}
function battleStatusMessage(){return `<div id="battle-message" class="battle-message" role="alert" ${battleError?'':'hidden'}>${esc(battleError)}</div>`;}
function battleLanding(){return `<div class="view battle-view"><div class="view-header battle-heading"><div><div class="eyebrow">À deux ou en groupe, partout dans le monde</div><h1>Jouons ensemble.</h1><p>Choisis un groupe ouvert selon son programme, crée ta battle mondiale ou retrouve tes amis en privé. L’hôte lance chaque partie quand vous êtes prêts.</p></div><span class="battle-stamp">${icon('flag')} 2 à 8 joueurs</span></div>${battleStatusMessage()}${!BATTLE_API_URL?'<div class="warning">Le service de battles est en cours de connexion. Le jeu solo reste accessible.</div>':''}<div class="battle-identity form-field"><label for="battle-name">Ton pseudo pour jouer en ligne</label><input id="battle-name" data-battle-field="name" value="${esc(battleDraft.name)}" maxlength="24" minlength="2" placeholder="Ex. Camille" autocomplete="nickname"><p class="form-hint">Un pseudo suffit pour rejoindre un groupe.</p></div><nav class="battle-entry-actions" aria-label="Choisir une partie en ligne"><button class="primary" data-battle-action="browse">${icon('globe')} Rejoindre un groupe mondial</button><button class="secondary" data-battle-action="create-open">${icon('flag')} Créer une partie</button><button class="text-button" data-battle-action="private-open">${icon('lock')} Rejoindre un groupe privé</button></nav><section class="battle-panel battle-directory" id="battle-world-groups"><div class="section-heading"><div><div class="eyebrow">Entrée directe, sans code</div><h2>Les groupes mondiaux ouverts</h2><p>Regarde les univers, le niveau et les places, puis rejoins le groupe qui te plaît.</p></div><button class="text-button" type="button" data-battle-action="refresh" ${!BATTLE_API_URL?'disabled':''}>${icon('repeat')} Actualiser</button></div><form class="battle-search" data-battle-form="search"><div class="form-field"><label for="battle-search">Rechercher un groupe</label><input id="battle-search" data-battle-field="search" value="${esc(battleDraft.search)}" maxlength="60" placeholder="Nom du groupe, hôte ou univers"></div><div class="form-field"><label for="battle-filterTheme">Univers proposé</label><select id="battle-filterTheme" data-battle-field="filterTheme"><option value="all">Tous les univers</option>${CATEGORIES.map(c=>`<option value="${c.id}" ${battleDraft.filterTheme===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><button type="submit" class="secondary" ${!BATTLE_API_URL?'disabled':''}>Rechercher</button></form><div id="battle-directory-list" aria-live="polite">${battleDirectory()}</div><small class="battle-directory-note">Les groupes privés se rejoignent avec leur code ou une invitation. Les groupes ouverts se mettent à jour automatiquement.</small></section><section class="battle-panel battle-create" id="battle-create-group"><div class="section-heading"><div><div class="eyebrow">Tu choisis le programme</div><h2>Créer ma partie</h2><p>Mélange plusieurs univers, choisis les options et ouvre ton groupe au monde ou à tes amis.</p></div>${icon('flag')}</div><form data-battle-form="create"><div class="form-field"><label for="battle-title">Nom du groupe</label><input id="battle-title" data-battle-field="title" value="${esc(battleDraft.title)}" maxlength="60" required placeholder="La battle du dimanche"></div>${battleThemePicker('create',battleDraft)}<div class="battle-form-grid">${battleSelect('battle-difficulty','Difficulté',[['all','Tous les niveaux'],[1,'Débutant'],[2,'Intermédiaire'],[3,'Avancé'],[4,'Expert']],battleDraft.difficulty)}${battleSelect('battle-count','Nombre de questions',[[8,'8 questions'],[12,'12 questions'],[20,'20 questions'],[50,'50 questions']],battleDraft.count)}${battleSelect('battle-maxPlayers','Taille du groupe',[[2,'2 joueurs · duel'],[3,'3 joueurs maximum'],[4,'4 joueurs maximum'],[5,'5 joueurs maximum'],[6,'6 joueurs maximum'],[7,'7 joueurs maximum'],[8,'8 joueurs maximum']],battleDraft.maxPlayers)}</div>${battleVisibilityPicker('create',battleDraft)}<div class="form-field battle-private-password" ${battleDraft.visibility==='public'?'hidden':''}><label for="battle-password">Mot de passe du groupe privé <span class="muted">(facultatif)</span></label><input id="battle-password" data-battle-field="password" value="${esc(battleDraft.password)}" type="password" maxlength="64" autocomplete="new-password" placeholder="À partager avec tes amis" ${battleDraft.visibility==='public'?'disabled':''}></div><p class="form-hint" data-battle-access-hint="create">${battleAccessHint(battleDraft)}</p><button type="submit" class="primary" ${battleBusy||!BATTLE_API_URL?'disabled':''}>Créer mon groupe ${icon('arrow')}</button></form></section><div class="battle-entry-grid"><section class="battle-panel" id="battle-private-group"><div class="eyebrow">Entre amis</div><h2>Rejoindre un groupe privé</h2><p>Saisis le code et l’éventuel mot de passe, ou accepte une invitation dans Mes amis.</p><form data-battle-form="join"><div class="form-field"><label for="battle-code">Code du groupe</label><input id="battle-code" data-battle-field="code" value="${esc(battleDraft.code)}" maxlength="12" required autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="Ex. ABC123"></div><div class="form-field"><label for="battle-joinPassword">Mot de passe <span class="muted">(si demandé)</span></label><input id="battle-joinPassword" data-battle-field="joinPassword" value="${esc(battleDraft.joinPassword)}" maxlength="64" type="password" autocomplete="off"></div><button class="secondary" type="submit" ${battleBusy||!BATTLE_API_URL?'disabled':''}>Rejoindre mes amis ${icon('arrow')}</button></form></section><section class="battle-panel battle-match"><div class="eyebrow">Un duel spontané</div><h2>Trouver un adversaire</h2><p>La recherche te met en relation avec un autre joueur sur le même thème. L’hôte lance le duel quand vous êtes prêts.</p><form data-battle-form="match"><div class="form-field"><label for="battle-matchTheme">Thème du duel</label><select id="battle-matchTheme" data-battle-field="matchTheme">${battleThemes(battleDraft.matchTheme)}</select></div><button class="secondary" type="submit" ${battleBusy||!BATTLE_API_URL?'disabled':''}>${icon('compass')} Chercher un adversaire</button></form><small>8 questions · 30 secondes par question</small></section></div><details class="battle-rules-details"><summary>Les règles : points, rapidité et sorties de page</summary>${battleRulesCard(true)}</details><p class="battle-footnote">Connexion Internet nécessaire. Les résultats de battle restent séparés de ton carnet solo.</p></div>`;}
function battleDirectory(){
  if(!battleListLoaded)return '<p class="battle-empty">Recherche des groupes ouverts…</p>';
  const term=battleDraft.search.trim().toLocaleLowerCase('fr').normalize('NFD').replace(/[\u0300-\u036f]/g,''),filter=battleDraft.filterTheme;
  const rooms=battleRooms.filter(r=>{
    if(r.locked||r.visibility==='private')return false;
    const themes=battleRoomThemes(r),label=[r.title,r.hostName,battleThemeLabel(themes)].join(' ').toLocaleLowerCase('fr').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    return (!term||term.split(/\s+/).every(word=>label.includes(word)))&&(filter==='all'||themes.includes('all')||themes.some(theme=>theme===filter||theme.startsWith(filter+'::')));
  });
  if(!rooms.length)return `<div class="battle-empty"><p>${battleRooms.length?'Aucun groupe ne correspond à ces filtres.':'Aucun groupe mondial ouvert pour le moment.'}</p><p>${battleRooms.length?'Essaie un autre univers ou efface la recherche.':'Crée ta partie mondiale : les prochains joueurs pourront la rejoindre ici.'}</p><button class="secondary" data-battle-action="${battleRooms.length?'clear-filters':'create-open'}" ${battleRooms.length?'':'data-world-public="true"'}>${battleRooms.length?'Voir tous les groupes':'Créer une partie mondiale'}</button></div>`;
  return `<p class="battle-directory-count">${rooms.length} groupe${rooms.length>1?'s':''} ouvert${rooms.length>1?'s':''}</p><div class="battle-world-grid">${rooms.map(r=>{const count=Number(r.questionCount||r.count),players=Number(r.players)||0,capacity=Number(r.maxPlayers)||8,canJoin=r.joinable!==false&&r.status!=='playing'&&r.status!=='finished'&&players<capacity;return `<article class="battle-world-card"><header><span class="pill">${icon('globe')} Mondial · ${r.status==='playing'?'En cours':'En attente'}</span><strong>${players} / ${capacity} joueurs</strong></header><h3>${esc(r.title)}</h3>${r.hostName?`<p class="battle-world-host">Hôte : ${esc(r.hostName)}</p>`:''}<div class="battle-world-themes">${battleRoomThemes(r).map(theme=>`<span>${esc(battleThemeLabel(theme))}</span>`).join('')}</div><dl><div><dt>Difficulté</dt><dd>${esc(DIFFICULTIES[r.difficulty]||'Tous les niveaux')}</dd></div><div><dt>Questions</dt><dd>${count}${Number(r.count)>count?' / '+Number(r.count)+' prévues':''}</dd></div><div><dt>Places libres</dt><dd>${Math.max(0,capacity-players)}</dd></div></dl><button class="primary" data-battle-action="join-open" data-code="${esc(r.code)}" data-joinable="${canJoin}" ${!canJoin||battleBusy?'disabled':''}>${canJoin?'Rejoindre ce groupe':players>=capacity?'Groupe complet':'Partie en cours'} ${icon('arrow')}</button><small>L’hôte lance la partie après votre arrivée.</small></article>`;}).join('')}</div>`;
}
function battleRenderDirectory(){
  const target=document.getElementById('battle-directory-list');if(!target)return;
  const active=document.activeElement,code=target.contains(active)?active?.dataset?.code:null,html=battleDirectory();
  if(target.innerHTML!==html){target.innerHTML=html;if(code)[...target.querySelectorAll('[data-code]')].find(button=>button.dataset.code===code&&!button.disabled)?.focus({preventScroll:true});}
}
function battleMe(){return battleRoom?.players?.find(p=>p.id===battleIdentity?.playerId);}
function battleActivePlayers(){return (battleRoom?.players||[]).filter(p=>!p.left);}
function battleHost(){return battleRoom?.hostId===battleIdentity?.playerId;}
function battleShareUrl(){return `${location.origin}${location.pathname}#battle=${encodeURIComponent(battleRoom?.code||battleIdentity?.code||'')}`;}
function battleRulesCard(newRoom=false){if(!newRoom&&!battleFairRules())return '<p class="battle-rule-legacy">Ce salon conserve son ancien barème, sans bonus de rapidité ni suivi des sorties de page.</p>';return `<aside class="battle-rules" aria-label="Règles des battles en ligne"><strong>${icon('flag')} Une battle équitable</strong><p>Une bonne réponse peut gagner jusqu’à <b>100 points de rapidité</b> en plus des points de base et de série. Ce bonus diminue sur 30 secondes : à 15 secondes, il reste environ 50 points.</p><p>Reste sur cette page pendant la question : une première sortie de plus d’une seconde fait perdre le bonus de rapidité de la question. Dès la deuxième sortie de la battle, la question concernée vaut <b>0 point</b>, même avec la bonne réponse. Le chronomètre continue.</p><small>Les sorties sont visibles par les adversaires. Le chat du salon et le panneau Mes amis restent utilisables ici. Une très brève perte de focus est tolérée.</small></aside>`;}
function battleQuestionNote(){return battleFairRules()?'Une seule bonne réponse. Réponse juste : points de base + série + jusqu’à 100 points de rapidité.':'Une seule bonne réponse. Chaque bonne réponse rapporte des points, sans bonus de vitesse.';}
function battleSpeedText(){const me=battleMe();if(me?.focusPenalty==='zero-points')return 'Cette question compte 0 point après une nouvelle sortie de page.';if(me?.focusPenalty==='no-speed-bonus')return 'Bonus de rapidité perdu pour cette question.';if(battleRoom?.reveal||me?.answered)return 'Le bonus de rapidité est calculé à l’envoi de la réponse.';const remaining=Math.max(0,Math.min(30000,(battleRoom?.deadline||0)-(Date.now()+battleServerOffset)));return `Bonus de rapidité estimé : jusqu’à +${Math.round((battleRoom?.rules?.speedBonusMax||100)*remaining/30000)} points si la réponse est juste.`;}
function battleUpdateSpeed(){const el=document.getElementById('battle-speed-value');if(el)el.textContent=battleSpeedText();}
function battleAnswerBreakdown(answer){const player=battleRoom.players.find(p=>p.id===answer.playerId);if(!battleFairRules())return `<span class="pill">${answer.correct?'✓':'×'} ${esc(player?.name||'Joueur')} · +${Number(answer.points)||0} pts</span>`;const penalty=answer.focusPenalty==='zero-points'?'Nouvelle sortie : cette réponse compte 0 point.':answer.focusPenalty==='no-speed-bonus'?'Première sortie : bonus de rapidité perdu.':'';return `<div class="battle-score-detail ${answer.focusPenalty?'battle-score-penalty':''}"><div><strong>${answer.correct?'✓':'×'} ${esc(player?.name||'Joueur')}</strong><strong>+${Number(answer.points)||0} pts</strong></div><p>Base <b>${Number(answer.basePoints)||0}</b> + série <b>${Number(answer.streakBonus)||0}</b> + rapidité <b>${Number(answer.speedBonus)||0}</b></p>${Number.isFinite(answer.responseMs)&&answer.responseMs>=0?`<small>Réponse reçue après ${(answer.responseMs/1000).toLocaleString('fr-FR',{maximumFractionDigits:1})} s.</small>`:''}${penalty?`<p class="battle-score-sanction">${penalty}</p>`:''}</div>`;}
function battleFocusSummary(player){if(!battleFairRules())return '';const departures=Number(player.departures)||0,questions=Number(player.penalizedQuestions)||0;return `<div class="battle-focus-summary"><strong>${departures} sortie${departures>1?'s':''} de page</strong><span>${questions} question${questions>1?'s':''} avec sanction</span></div>`;}
function battleLeaderboard(final=false){const room=battleRoom,players=[...(room.players||[])].sort((a,b)=>Number(!!a.left)-Number(!!b.left)||b.score-a.score||b.correct-a.correct||a.name.localeCompare(b.name));return `<section class="battle-panel battle-ranking"><h2>${final?'Le classement final':'Le classement'}</h2><div class="battle-table-wrap"><table class="battle-table"><thead><tr><th scope="col">Place</th><th scope="col">Joueur</th><th scope="col" title="Bonnes réponses">Réussites</th>${battleFairRules()?'<th scope="col" title="Sorties de page pendant les questions">Sorties</th>':''}<th scope="col">Points</th></tr></thead><tbody>${players.map((p,i)=>`<tr class="${p.id===battleIdentity?.playerId?'battle-me':''}"><td>${p.left?'—':p.rank||i+1}${!p.left&&(p.rank||i+1)===1?' ✦':''}</td><th scope="row">${esc(p.name)}${p.id===battleIdentity?.playerId?' <small>(toi)</small>':''}${p.id===room.hostId?' <small>· hôte</small>':''}${p.left?' <small>· forfait</small>':p.away?' <small class="battle-away-status">· hors de la page</small>':p.connected===false?' <small>· absent</small>':''}</th><td>${Number(p.correct)||0} / ${room.questionCount}</td>${battleFairRules()?`<td class="battle-departures">${Number(p.departures)||0}${p.focusPenalty?`<small>${p.focusPenalty==='zero-points'?'0 pt sur cette question':'bonus perdu'}</small>`:''}</td>`:''}<td><strong>${fmt(p.score||0)}</strong></td></tr>`).join('')}</tbody></table></div></section>`;}
function battleLobby(){const room=battleRoom,isHost=battleHost(),players=battleActivePlayers(),ready=players.filter(p=>p.connected!==false).length;return `<section class="battle-panel battle-lobby"><div class="battle-lobby-head"><div><div class="eyebrow">${room.matchmaking?'Recherche d’adversaire':battleRoomVisibility(room)==='public'?'Groupe mondial ouvert':'Groupe privé entre amis'}</div><h2>${esc(room.title)}</h2><p>${esc(battleThemeLabel(room))} · ${DIFFICULTIES[room.difficulty]||'Tous les niveaux'} · ${room.questionCount||room.count} questions · 30 s par question</p></div><div class="battle-code-box"><small>Code du salon</small><strong>${esc(room.code)}</strong><button class="text-button" data-battle-action="copy">Copier le lien d’invitation</button></div></div><div class="battle-players">${players.map(p=>`<div class="battle-player"><span class="battle-avatar">${esc(p.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(p.name)}${p.id===battleIdentity?.playerId?' (toi)':''}</strong><small>${p.id===room.hostId?'Hôte du salon':p.connected===false?'En attente de reconnexion':'Prêt à jouer'}</small></div></div>`).join('')}</div><div class="battle-lobby-bottom"><p class="battle-wait">${ready<2?(battleRoomVisibility(room)==='public'?'Ton groupe est ouvert : les joueurs peuvent le rejoindre depuis la liste mondiale.':'En attente d’un adversaire. Invite tes amis ou partage le lien et le code.'):isHost?'Tout le monde est arrivé ? Tu peux lancer la battle.':'Les joueurs sont prêts. L’hôte lance la battle.'}</p>${isHost?`<button class="primary" data-battle-action="start" ${ready<2||battleBusy?'disabled':''}>Lancer la battle ${icon('flag')}</button>`:'<span class="pill">En attente de l’hôte</span>'}</div><p class="form-hint">${room.locked?'Ce salon est protégé par mot de passe. ':''}${battleRoomVisibility(room)==='public'?'Ce groupe est visible dans la liste mondiale et se rejoint directement.':'Ce groupe privé se rejoint avec son code, son lien ou une invitation.'} ${players.length} / ${room.maxPlayers} joueurs. L’hôte lance la partie quand les joueurs sont prêts.</p><div class="battle-group-tools"><button class="secondary" data-social-action="invite-open">${icon('book')} Inviter mes amis</button><small>Les amis invités te rejoignent directement, sans saisir le code.</small></div>${battleGroupOptions()}${battleRulesCard()}</section>`;}
function battleQuestion(){const room=battleRoom,q=room.question,me=battleMe(),reveal=room.reveal,ownAnswer=reveal?.answers?.find(a=>a.playerId===battleIdentity?.playerId),selected=ownAnswer?.selected??(battlePendingAnswer?.index===room.questionIndex?battlePendingAnswer.selected:null),c=CATEGORIES.find(c=>c.id===q?.category);if(!q)return '<div class="battle-panel"><p>La prochaine question arrive…</p></div>';return `<div class="battle-game-layout"><section><div class="game-toolbar"><span class="pill">Question ${room.questionIndex+1} / ${room.questionCount}</span><span class="timer" id="battle-timer">${icon('clock')} <span id="battle-timer-value">${reveal?'Correction':battleSeconds()+' s'}</span></span></div><div class="game-progress" role="progressbar" aria-label="Progression de la battle" aria-valuenow="${room.questionIndex+(reveal?1:0)}" aria-valuemin="0" aria-valuemax="${room.questionCount}"><span style="width:${100*(room.questionIndex+(reveal?1:0))/room.questionCount}%"></span></div><article class="question-card"><div class="question-top"><div class="question-tags"><span class="pill">${c?icon(c.icon):''}${esc(c?.name||q.category)}</span><span class="pill">${esc(q.subtheme)}</span></div><span class="tag muted">${DIFFICULTIES[q.difficulty]||''}</span></div><h2 class="battle-question-title" id="battle-question-title" tabindex="-1">${esc(q.question)}</h2><p class="question-note">${battleQuestionNote()}</p>${battleFairRules()?`<p class="battle-speed" id="battle-speed-value">${esc(battleSpeedText())}</p>`:''}<div class="answers">${q.options.map((text,i)=>`<button class="answer ${reveal&&i===reveal.correct?'correct':reveal&&i===selected?'wrong':i===selected?'battle-selected':''}" data-battle-action="answer" data-selected="${i}" ${me?.answered||reveal||battleBusy?'disabled':''}><span class="answer-key">${String.fromCharCode(65+i)}</span><span>${esc(text)}${reveal&&i===reveal.correct?'<span class="answer-status">✓ Bonne réponse</span>':i===selected?'<span class="answer-status">Ta réponse</span>':''}</span></button>`).join('')}</div><p class="battle-answer-status" role="status">${reveal?'Tout le monde a répondu ou le temps est écoulé.':me?.answered?'Réponse enregistrée. Attendons les autres joueurs.':battleBusy?'Envoi de ta réponse…':'À toi de jouer !'} ${room.players.filter(p=>p.answered).length} / ${room.players.length} réponses.</p></article>${reveal?`<section class="correction"><div class="correction-title">${icon('book')} Le déclic à partager</div><p><strong>${esc(q.options[reveal.correct]||'')}</strong></p><p class="explain">${esc(reveal.explanation)}</p><div class="battle-answer-recap">${(reveal.answers||[]).map(battleAnswerBreakdown).join('')}</div></section><div class="game-next">${battleHost()?`<small>Laisse à chacun le temps de lire l’explication.</small><button class="primary" data-battle-action="next" ${battleBusy?'disabled':''}>${room.questionIndex+1>=room.questionCount?'Voir le classement final':'Question suivante'} ${icon('arrow')}</button>`:'<small class="battle-wait">L’hôte continue quand tout le monde est prêt.</small>'}</div>`:''}</section><aside>${battleLeaderboard()}</aside></div>`;}
function battleSkillList(items,empty){return items?.length?`<ul>${items.map(s=>`<li><strong>${esc(s.name)}</strong><span>${Number(s.correct)} / ${Number(s.total)} réussites</span></li>`).join('')}</ul>`:`<p class="muted">${empty}</p>`;}
function battleResults(){const room=battleRoom,winners=room.players.filter(p=>(room.winners||[]).includes(p.id)),title=winners.length>1?`Égalité entre ${winners.map(p=>p.name).join(' et ')} !`:winners.length?`${winners[0].name} remporte la battle !`:'La battle est terminée.';return `<section class="battle-result-hero"><span class="battle-result-icon">${icon('cup')}</span><div class="eyebrow">Une battle, de nouveaux déclics</div><h2>${esc(title)}</h2><p>${esc(battleThemeLabel(room))} · ${room.questionCount} questions jouées ensemble.</p></section>${battleGroupOptions(true)}<div class="battle-group-tools"><button class="secondary" data-social-action="invite-open">Inviter mes amis pour la suite</button></div>${battleLeaderboard(true)}<div class="battle-results-grid">${room.players.map(p=>`<section class="battle-panel battle-player-report"><h2>${esc(p.name)}${p.id===battleIdentity?.playerId?' · toi':''}</h2><p class="battle-report-score">${fmt(p.score||0)} points <span>· ${Number(p.correct)||0} / ${room.questionCount} bonnes réponses</span></p>${battleFocusSummary(p)}<h3>Points forts de cette battle</h3>${battleSkillList(p.strengths,'Les points forts se dessineront au fil des prochaines battles.')}<h3>À retravailler</h3>${battleSkillList(p.weaknesses,'Aucune notion à retravailler relevée sur cette battle.')}<small>Ce bilan porte seulement sur les questions de cette battle.</small></section>`).join('')}</div><div class="result-actions"><button class="secondary" data-battle-action="leave">Quitter ce groupe</button><button class="secondary" data-action="home">Retour aux univers</button></div>`;}
function battleLive(){if(!battleRoom)return '<section class="battle-panel"><p>Reconnexion au salon…</p><button class="secondary" data-battle-action="retry">Réessayer</button></section>';if(battleRoom.status==='closed')return '<section class="battle-panel"><h2>Ce salon est fermé.</h2><p>Tu peux créer ou rejoindre une autre battle.</p><button class="primary" data-battle-action="leave">Retour aux battles</button></section>';return battleRoom.status==='finished'?battleResults():battleRoom.status==='playing'?battleQuestion():battleLobby();}
function renderBattle(){if(!battleIdentity)return battleLanding();return `<div class="view battle-view"><div class="battle-room-toolbar"><button class="text-button" data-action="home">${icon('arrow')} Retour aux univers</button><span class="pill" id="battle-group-status">Groupe ${esc(battleIdentity.code)} · manche ${battleRoundId()}</span><button class="text-button" data-social-action="room-chat">Chat du salon</button><button class="text-button" data-social-action="invite-open">Inviter mes amis</button><button class="text-button" data-battle-action="leave">Quitter la battle ${icon('close')}</button></div>${battleStatusMessage()}<div id="battle-attention-notice" class="battle-attention-notice" role="alert" ${battleAttentionNotice()?'':'hidden'}>${esc(battleAttentionNotice())}</div><div id="battle-live">${battleLive()}</div>${renderRoomChat()}</div>`;}
async function battleApi(action,payload={},identity=battleIdentity){if(!BATTLE_API_URL)throw Error('Le service de battles n’est pas encore connecté.');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const response=await fetch(BATTLE_API_URL.replace(/\/$/,'')+'/api',{method:'POST',headers:{'Content-Type':'application/json',...(identity?.token?{Authorization:'Bearer '+identity.token}:{})},body:JSON.stringify({action,...payload}),signal:controller.signal,cache:'no-store'});let data;try{data=await response.json();}catch{throw Error('Le serveur de battles ne répond pas correctement. Réessaie dans un instant.');}if(!response.ok||data.error)throw Object.assign(Error(typeof data.error==='string'?data.error:data.error?.message||'Cette action n’a pas pu être effectuée.'),{status:response.status});return data;}catch(error){if(error.name==='AbortError')throw Error('La connexion prend trop de temps. Vérifie Internet et réessaie.');if(error instanceof TypeError)throw Error('Connexion au salon interrompue. Vérifie Internet ; une reconnexion est tentée automatiquement.');throw error;}finally{clearTimeout(timeout);}}
function battleSetError(message){battleError=message;const el=document.getElementById('battle-message');if(el){el.textContent=message;el.hidden=!message;}}
function battleSetBusy(busy){
  battleBusy=busy;
  document.querySelectorAll('[data-battle-form] button[type="submit"],[data-battle-action="start"],[data-battle-action="answer"],[data-battle-action="next"],[data-battle-action="join-open"]').forEach(el=>{
    el.disabled=busy||!BATTLE_API_URL;
    if(el.dataset.battleAction==='join-open')el.disabled=busy||!BATTLE_API_URL||el.dataset.joinable!=='true';
    if(!busy&&el.dataset.battleAction==='answer')el.disabled=!!battleMe()?.answered||!!battleRoom?.reveal;
    if(!busy&&el.dataset.battleAction==='start')el.disabled=battleActivePlayers().filter(p=>p.connected!==false).length<2||battleGroupDirty();
    if(el.closest('[data-battle-form="room-configure"],[data-battle-form="round-next"]')&&Number(battleRoundDraft.maxPlayers)<battleActivePlayers().length)el.disabled=true;
  });
  battleUpdateGroupCapacity();
}
function battleUpdateGroupCapacity(){
  const select=document.getElementById('battle-round-maxPlayers');if(!select)return;
  const needed=battleActivePlayers().length;
  for(const option of select.options)option.disabled=Number(option.value)<needed;
  const warning=document.querySelector('[data-battle-capacity-warning]');if(warning){warning.hidden=Number(select.value)>=needed;warning.textContent=warning.hidden?'':`Le groupe compte maintenant ${needed} membres. Choisis au moins ${needed} places.`;}
}
function battleSeconds(){return Math.max(0,Math.ceil(((battleRoom?.deadline||0)-(Date.now()+battleServerOffset))/1000));}
function battleUpdateClock(){battleUpdateSpeed();const el=document.getElementById('battle-timer-value');if(!el)return;const seconds=battleSeconds();el.textContent=battleRoom?.reveal?'Correction':seconds+' s';document.getElementById('battle-timer')?.classList.toggle('urgent',!battleRoom?.reveal&&seconds<8);}
function battleUpdateLive(force=false){
  if(view!=='battle')return;const target=document.getElementById('battle-live');if(!target)return;
  const signature=JSON.stringify(battleRoom?{...battleRoom,serverNow:0}:null);
  if(force||signature!==battleLiveSignature){
    const previous=document.activeElement,focusedAction=previous?.dataset?.battleAction,focusedSelected=previous?.dataset?.selected,oldQuestion=target.querySelector('#battle-question-title')?.textContent;
    const savedForm=target.querySelector('form[data-round-key]'),focusedInForm=!!savedForm?.contains(previous);
    target.innerHTML=battleLive();battleLiveSignature=signature;
    const replacement=target.querySelector('form[data-round-key]');
    if(savedForm&&replacement?.dataset.roundKey===savedForm.dataset.roundKey&&replacement.dataset.battleForm===savedForm.dataset.battleForm){replacement.replaceWith(savedForm);if(focusedInForm)previous.focus({preventScroll:true});}
    if(focusedAction){const candidate=[...target.querySelectorAll('[data-battle-action]')].find(el=>el.dataset.battleAction===focusedAction&&el.dataset.selected===focusedSelected);candidate?.focus({preventScroll:true});}
    const question=target.querySelector('#battle-question-title');if(question&&question.textContent!==oldQuestion&&oldQuestion&&!previous?.closest('#battle-chat,#social-dock-root'))question.focus({preventScroll:true});
    battleSetBusy(battleBusy);
  }
  battleUpdateClock();
}
function battleAcceptRoom(room){
  if(!room)return;
  const oldRound=battleRoundId(),newRound=battleRoundId(room),sameCode=battleRoom?.code===room.code;
  if(sameCode){
    if(Number.isSafeInteger(room.revision)&&Number.isSafeInteger(battleRoom.revision)&&room.revision<battleRoom.revision)return;
    if(newRound<oldRound)return;
    if(newRound===oldRound){const phases={waiting:0,playing:1,finished:2,closed:3},me=battleMe(),next=room.players?.find(p=>p.id===battleIdentity?.playerId);if((phases[room.status]??0)<(phases[battleRoom.status]??0)||room.questionIndex<battleRoom.questionIndex||(room.questionIndex===battleRoom.questionIndex&&((battleRoom.reveal&&!room.reveal)||(me?.answered&&!next?.answered)||(me?.departures||0)>(next?.departures||0))))return;}
  }
  const before=battleRoom?.questionIndex,oldStatus=battleRoom?.status,newRoundStarted=sameCode&&newRound>oldRound;
  if(newRoundStarted){battleAttentionReset();battleRoundDraft.key='';battlePendingAnswer=null;}
  battleRoom=room;if(Number.isFinite(room.serverNow))battleServerOffset=room.serverNow-Date.now();
  const groupStatus=document.getElementById('battle-group-status');if(groupStatus)groupStatus.textContent=`Groupe ${room.code} · manche ${newRound}`;
  if(room.status==='closed')battleStopPolling();if(before!==room.questionIndex)battlePendingAnswer=null;
  battleUpdateLive();battleAttentionReconcile();socialUpdateLayout();socialRenderDock();socialUpdateDashboard();
  if(view==='battle'&&!document.activeElement?.closest('#battle-chat,#social-dock-root')&&(newRoundStarted||(room.status==='playing'&&(oldStatus!=='playing'||before!==room.questionIndex))||(room.status==='finished'&&oldStatus!=='finished')))document.getElementById('battle-live')?.scrollIntoView({block:'start',behavior:'instant'});
}
async function battleRefresh(){if(!battleIdentity||battleFetching||view!=='battle'||!BATTLE_API_URL)return;const epoch=battleEpoch;battleFetching=true;try{const data=await battleApi('status',{code:battleIdentity.code});if(epoch!==battleEpoch)return;battleSetError('');battleAcceptRoom(data.room);}catch(error){if(epoch!==battleEpoch)return;battleSetError(error.message);if(error.status===404||error.status===401||error.status===410){battleRoom={status:'closed',players:[],code:battleIdentity.code};battleUpdateLive();}}finally{battleFetching=false;}}
function battleStopPolling(){clearInterval(battlePoll);clearInterval(battleClock);clearInterval(battleDirectoryPoll);battlePoll=null;battleClock=null;battleDirectoryPoll=null;}
function battleAfterRender(){
  battleAttentionReconcile();if(view!=='battle'){battleStopPolling();return;}battleLiveSignature='';
  if(battleIdentity){clearInterval(battleDirectoryPoll);battleDirectoryPoll=null;if(!battlePoll&&battleRoom?.status!=='closed'){battlePoll=setInterval(battleRefresh,1500);battleClock=setInterval(battleUpdateClock,250);battleRefresh();}battleUpdateClock();}
  else if(BATTLE_API_URL){if(!battleListLoaded)battleLoadList();if(!battleDirectoryPoll)battleDirectoryPoll=setInterval(battleLoadList,8000);}
}
async function battleLoadList(){
  const epoch=battleEpoch,request=++battleDirectoryRequest;
  try{const data=await battleApi('list',{},null);if(epoch!==battleEpoch||request!==battleDirectoryRequest||battleIdentity)return;battleRooms=data.rooms||[];battleListLoaded=true;battleRenderDirectory();battleSetError('');}
  catch(error){if(epoch!==battleEpoch||request!==battleDirectoryRequest||battleIdentity)return;battleListLoaded=true;battleSetError(error.message);const el=document.getElementById('battle-directory-list');if(el)el.innerHTML='<p class="battle-empty">Groupes momentanément indisponibles. Utilise Actualiser pour réessayer.</p>';}
}
function battleName(){const name=battleDraft.name.trim();if(name.length<2){const el=document.getElementById('battle-name');el?.focus();throw Error('Choisis un pseudo d’au moins deux caractères avant de rejoindre une battle.');}try{localStorage.setItem(BATTLE_NAME_KEY,name);}catch{}return name;}
function battleEnter(data){if(!data.room||!data.token||!data.playerId)throw Error('Le serveur n’a pas confirmé ton entrée dans le salon.');battleEpoch++;battleAttentionReset();battleRoundDraft.key='';battleIdentity={code:data.room.code,token:data.token,playerId:data.playerId};battleRoom=data.room;view='battle';battleRemember();battleDraft.password='';battleDraft.joinPassword='';battleError='';history.replaceState(null,'','#battle='+encodeURIComponent(data.room.code));battleStopPolling();render();}
async function battleSubmit(type){
  if(battleBusy)return;const epoch=battleEpoch,identity=battleIdentity?{...battleIdentity}:null,roundId=battleRoundId();battleSetBusy(true);battleSetError('');
  try{
    if(type==='search'){await battleLoadList();return;}
    if(type==='room-configure'||type==='round-next'){
      if(!identity||!battleHost())throw Error('Seul l’hôte peut préparer cette manche.');
      const d={...battleGroupDraft()},themes=battleChosenThemes(d),data=await battleApi(type,{code:identity.code,roundId,theme:themes.length===1?themes[0]:'mixed',themes,visibility:d.visibility,difficulty:d.difficulty==='all'?'all':Number(d.difficulty),count:Number(d.count),maxPlayers:Number(d.maxPlayers),listed:d.visibility==='public'},identity);
      if(epoch!==battleEpoch)return;battleAcceptRoom(data.room);notify(type==='round-next'?'La partie suivante est prête. L’hôte peut la lancer.':'Les options du groupe sont enregistrées.');return;
    }
    const name=battleName();let data;
    if(type==='match')data=await battleApi('match',{name,theme:battleDraft.matchTheme});
    else if(type==='join')data=await battleApi('join',{name,code:battleDraft.code.trim().toUpperCase(),password:battleDraft.joinPassword});
    else if(type==='create'){const themes=battleChosenThemes(battleDraft);data=await battleApi('create',{name,title:battleDraft.title.trim(),theme:themes.length===1?themes[0]:'mixed',themes,visibility:battleDraft.visibility,difficulty:battleDraft.difficulty==='all'?'all':Number(battleDraft.difficulty),count:Number(battleDraft.count),maxPlayers:Number(battleDraft.maxPlayers),listed:battleDraft.visibility==='public',password:battleDraft.visibility==='private'?battleDraft.password:''});}
    if(data&&epoch===battleEpoch)battleEnter(data);
  }catch(error){if(epoch===battleEpoch)battleSetError(error.message);}finally{battleSetBusy(false);}
}
async function battleAction(el){
  const action=el.dataset.battleAction;
  if(action==='refresh'){await battleLoadList();return;}
  if(action==='browse'||action==='create-open'||action==='private-open'){
    if(el.dataset.worldPublic==='true'){const radio=document.querySelector('[data-battle-field=visibility][value=public]');if(radio){radio.checked=true;radio.dispatchEvent(new Event('change',{bubbles:true}));}}
    const id=action==='browse'?'battle-world-groups':action==='create-open'?'battle-create-group':'battle-private-group';
    document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});if(action==='private-open')document.getElementById('battle-code')?.focus({preventScroll:true});return;
  }
  if(action==='clear-filters'){battleDraft.search='';battleDraft.filterTheme='all';const search=document.getElementById('battle-search'),filter=document.getElementById('battle-filterTheme');if(search)search.value='';if(filter)filter.value='all';battleRenderDirectory();return;}
  if(action==='choose'||action==='join-open'){
    if(el.dataset.locked==='true'){battleDraft.code=el.dataset.code;const input=document.getElementById('battle-code');if(input)input.value=battleDraft.code;document.getElementById('battle-private-group')?.scrollIntoView({behavior:'smooth',block:'start'});document.getElementById('battle-joinPassword')?.focus({preventScroll:true});return;}
    if(battleBusy)return;const epoch=battleEpoch;battleSetBusy(true);battleSetError('');
    try{const name=battleName(),data=await battleApi('join',{name,code:el.dataset.code,password:''},null);if(epoch===battleEpoch)battleEnter(data);}
    catch(error){if(epoch===battleEpoch){if(error.status===409||error.status===404)await battleLoadList();if(epoch===battleEpoch)battleSetError(error.message);}}
    finally{battleSetBusy(false);}return;
  }
  if(action==='copy'){try{await navigator.clipboard.writeText(battleShareUrl());notify('Lien d’invitation copié. Tu peux aussi inviter directement tes amis depuis le panneau Mes amis.');}catch{battleSetError('Voici le lien à copier : '+battleShareUrl());}return;}
  if(action==='retry'){await battleRefresh();return;}
  if(battleBusy)return;
  if(action==='leave'){battleSetBusy(true);try{if(battleIdentity)await battleApi('leave',{code:battleIdentity.code});}catch{/* Une sortie locale reste possible si le réseau est coupé. */}finally{battleEpoch++;battleStopPolling();battleAttentionReset();battleIdentity=null;battleRoom=null;battlePendingAnswer=null;battleRoundDraft.key='';battleRemember();battleError='';battleListLoaded=false;battleBusy=false;history.replaceState(null,'',location.pathname+location.search);render();}return;}
  const epoch=battleEpoch,identity=battleIdentity?{...battleIdentity}:null,roundId=battleRoundId();if(!identity)return;
  battleSetBusy(true);battleSetError('');
  try{
    const payload={code:identity.code,roundId};
    if(action==='answer'){
      const intendedQuestion=battleRoom.questionIndex;await battleAttentionBeforeAnswer(intendedQuestion,roundId);
      if(epoch!==battleEpoch||battleRoundId()!==roundId)throw Error('La manche a changé. Attends la nouvelle question.');
      payload.questionIndex=intendedQuestion;payload.selected=Number(el.dataset.selected);battlePendingAnswer={roundId,index:payload.questionIndex,selected:payload.selected};
    }
    const data=await battleApi(action,payload,identity);if(epoch===battleEpoch)battleAcceptRoom(data.room);
  }catch(error){if(epoch===battleEpoch){if(action==='answer')battlePendingAnswer=null;battleSetError(error.message);await battleRefresh();}}
  finally{if(epoch===battleEpoch){battleSetBusy(false);battleUpdateLive(true);}}
}
function battleBoot(){const params=new URLSearchParams(location.hash.replace(/^#/,'')),code=params.get('battle');if(location.hash==='#friends'){view='friends';render();}else if(location.hash==='#battles'){view='battle';render();}else if(code&&code.length<=12){battleDraft.code=code.toUpperCase();view='battle';render();}else if(battleIdentity){view='battle';render();}}
document.addEventListener('submit',event=>{const form=event.target.closest('[data-battle-form]');if(!form)return;event.preventDefault();battleSubmit(form.dataset.battleForm);});

function battleFieldChanged(event){
  const input=event.target,themeChoice=input.dataset?.battleThemeChoice;
  if(themeChoice&&event.type==='change'){
    const scope=input.dataset.battleThemeScope,d=scope==='round'?battleRoundDraft:battleDraft,current=battleNormalizeThemes(d.themes);
    d.themes=themeChoice==='all'?(input.checked?['all']:[]):battleNormalizeThemes(input.checked?[...current.filter(key=>key!=='all'),themeChoice]:current.filter(key=>key!==themeChoice&&!key.startsWith(themeChoice+'::')));
    d.theme=d.themes.length===1?d.themes[0]:'mixed';battleUpdateThemePicker(scope);battleSetBusy(battleBusy);return;
  }
  const field=input.dataset?.battleField,groupField=input.dataset?.battleRoundField,d=groupField?battleRoundDraft:battleDraft,key=groupField||field;
  if(!key||!(key in d)||input.type==='radio'&&!input.checked)return;
  d[key]=input.type==='checkbox'?input.checked:input.value;
  if(key==='name'&&!groupField&&d.name.trim().length>=2&&battleError.startsWith('Choisis un pseudo'))battleSetError('');
  if(key==='theme'){d.themes=battleNormalizeThemes([d.theme]);battleUpdateThemePicker(groupField?'round':'create');}
  if(key==='visibility'){
    d.listed=d.visibility==='public';const scope=groupField?'round':'create',hint=document.querySelector(`[data-battle-access-hint="${scope}"]`);if(hint)hint.textContent=battleAccessHint(d,!!groupField);
    if(!groupField){const box=document.querySelector('.battle-private-password'),password=document.getElementById('battle-password');if(box)box.hidden=d.visibility==='public';if(password)password.disabled=d.visibility==='public';}
  }
  if(key==='search'||key==='filterTheme')battleRenderDirectory();
  battleSetBusy(battleBusy);
}
document.addEventListener('input',battleFieldChanged);
document.addEventListener('change',battleFieldChanged);
document.addEventListener('click',event=>{const el=event.target.closest('[data-battle-action]');if(!el)return;event.preventDefault();battleAction(el);});
document.addEventListener('keydown',event=>{if(event.target.closest('#social-dock-root,#battle-chat')||view!=='battle'||event.ctrlKey||event.altKey||event.metaKey||['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName)||document.querySelector('dialog[open]'))return;if(battleRoom?.status!=='playing'||battleRoom?.reveal||battleMe()?.answered||battleBusy)return;const index=/^[1-4]$/.test(event.key)?Number(event.key)-1:['a','b','c','d'].indexOf(event.key.toLowerCase());const button=document.querySelector(`[data-battle-action="answer"][data-selected="${index}"]`);if(button&&!button.disabled){event.preventDefault();battleAction(button);}});
window.addEventListener('hashchange',battleBoot);
window.addEventListener('pagehide',battleStopPolling);
